arguments.file_text:
namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string InstructorName { get; set; }
    public required string InstructorBio { get; set; }
    public required string DepartmentCode { get; set; }
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public required string Code { get; set; }
    public required string Name { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string Name { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]+$", ErrorMessage = "Student ID must be alphanumeric.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    IReadOnlyList<Course> GetCourses(string? search = null, string? departmentCode = null);
    IReadOnlyList<Course> GetFeaturedCourses();
    Course? GetCourseById(int id);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Code = "CS", Name = "Computer Science" },
        new() { Code = "MATH", Name = "Mathematics" },
        new() { Code = "ENG", Name = "English" },
        new() { Code = "PHYS", Name = "Physics" },
        new() { Code = "HIST", Name = "History" },
    ];

    private static readonly List<Course> Courses =
    [
        new()
        {
            Id = 1, Code = "CS 101", Title = "Introduction to Programming",
            Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control flow, functions, data structures, and basic algorithms.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen",
            InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She received her PhD from MIT and has published extensively on programming pedagogy.",
            DepartmentCode = "CS", IsFeatured = true
        },
        new()
        {
            Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms",
            Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms).",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. Bob Martinez",
            InstructorBio = "Dr. Martinez specializes in algorithm optimization and competitive programming. He holds multiple ICPC medals and has mentored national programming teams.",
            DepartmentCode = "CS", IsFeatured = true
        },
        new()
        {
            Id = 3, Code = "CS 310", Title = "Database Systems",
            Description = "Design and implementation of relational database systems. Covers SQL, normalization, transaction processing, query optimization, and introduction to NoSQL databases.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Carol Singh",
            InstructorBio = "Dr. Singh worked at Oracle for a decade before joining academia. Her research focuses on distributed database architectures and query optimization.",
            DepartmentCode = "CS", IsFeatured = false
        },
        new()
        {
            Id = 4, Code = "MATH 101", Title = "Calculus I",
            Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.",
            Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. David Park",
            InstructorBio = "Dr. Park is an award-winning educator who has taught calculus for over 20 years. He is known for making complex mathematical concepts accessible and engaging.",
            DepartmentCode = "MATH", IsFeatured = true
        },
        new()
        {
            Id = 5, Code = "MATH 201", Title = "Linear Algebra",
            Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to computer graphics and machine learning.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Elena Rossi",
            InstructorBio = "Dr. Rossi's research bridges pure mathematics and machine learning. She has co-authored two textbooks on linear algebra for applied scientists.",
            DepartmentCode = "MATH", IsFeatured = false
        },
        new()
        {
            Id = 6, Code = "ENG 101", Title = "College Composition",
            Description = "Develop writing skills through essay composition, research methods, and critical analysis. Emphasis on clear argumentation and proper citation.",
            Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. Frank Liu",
            InstructorBio = "Prof. Liu is a published novelist and essayist. He brings creative writing techniques into academic composition to help students find their voice.",
            DepartmentCode = "ENG", IsFeatured = false
        },
        new()
        {
            Id = 7, Code = "ENG 250", Title = "American Literature",
            Description = "Survey of American literature from the colonial period to the present. Examines major works and literary movements in their historical context.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Grace Thompson",
            InstructorBio = "Dr. Thompson is a Pulitzer Prize-nominated critic specializing in 20th-century American fiction. She has lectured at universities across three continents.",
            DepartmentCode = "ENG", IsFeatured = true
        },
        new()
        {
            Id = 8, Code = "PHYS 101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions demonstrating physical principles through hands-on experimentation.",
            Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. Henry Nakamura",
            InstructorBio = "Dr. Nakamura is a former NASA researcher whose work on fluid dynamics in microgravity environments has been published in Nature and Science.",
            DepartmentCode = "PHYS", IsFeatured = false
        },
        new()
        {
            Id = 9, Code = "PHYS 220", Title = "Quantum Mechanics",
            Description = "Introduction to quantum theory: wave-particle duality, Schrödinger equation, hydrogen atom, spin, and quantum entanglement.",
            Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", InstructorName = "Dr. Irene Volkov",
            InstructorBio = "Dr. Volkov conducted post-doctoral research at CERN and specializes in quantum information theory. She has received multiple NSF grants for her work.",
            DepartmentCode = "PHYS", IsFeatured = true
        },
        new()
        {
            Id = 10, Code = "HIST 101", Title = "World History to 1500",
            Description = "Survey of world civilizations from ancient times to the early modern period. Explores political, economic, social, and cultural developments across regions.",
            Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", InstructorName = "Dr. James Okafor",
            InstructorBio = "Dr. Okafor has excavated archaeological sites in West Africa and the Mediterranean. His interdisciplinary approach integrates archaeology, oral history, and textual analysis.",
            DepartmentCode = "HIST", IsFeatured = false
        },
    ];

    public IReadOnlyList<Department> GetDepartments() => Departments;

    public IReadOnlyList<Course> GetCourses(string? search = null, string? departmentCode = null)
    {
        var query = Courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentCode))
        {
            query = query.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(search, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        Courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourseById(int id) =>
        Courses.FirstOrDefault(c => c.Id == id);
}

