@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center mb-4">
    <h1>University Course Catalog</h1>
    <p class="lead">Explore departments and courses for the upcoming semester.</p>
</div>

<section class="mb-5">
    <h2>Featured Courses</h2>
    <div class="row">
        @foreach (var course in featuredCourses)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@course.Code</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@course.Title</h6>
                        <p class="card-text">@course.Credits credits &middot; @course.InstructorName</p>
                        <a href="/courses/@course.Id" class="btn btn-primary btn-sm">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

<section>
    <h2>Departments</h2>
    <div class="list-group">
        @foreach (var dept in departments)
        {
            <a href="/courses?department=@dept.Code" class="list-group-item list-group-item-action">
                <strong>@dept.Code</strong> &mdash; @dept.Name
            </a>
        }
    </div>
</section>

@code {
    private IReadOnlyList<Course> featuredCourses = [];
    private IReadOnlyList<Department> departments = [];

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }
}

